def _src(from_: str, subject: str, body: str) -> dict[str, str]:
    return {"from": from_, "subject": subject, "body": body}


def _message_prompts(lesson: str, entries: list[tuple[str, str]]) -> list[dict[str, Any]]:
    return [
        {
            "id": f"{lesson}-pe-{index}",
            "title": title,
            "situation": "",
            "instruction": instruction,
            "points": [],
        }
        for index, (title, instruction) in enumerate(entries, 1)
    ]


def _email_prompts(
    lesson: str, entries: list[tuple[str, str, dict[str, str]]]
) -> list[dict[str, Any]]:
    return [
        {
            "id": f"{lesson}-pee-{index}",
            "title": title,
            "situation": "",
            "sourceMessage": source_message,
            "instruction": instruction,
            "points": [],
        }
        for index, (title, instruction, source_message) in enumerate(entries, 1)
    ]


